<script>
  const player = document.getElementById('fullPlayer');
  const openPlayer = document.getElementById('openPlayer');
  const closePlayer = document.getElementById('closePlayer');
  const fullPlay = document.getElementById('fullPlay');
  const topPlay = document.querySelector('.top-control.playpause');
  let playing = false;
  let seconds = 11;
  let timer;

  function updatePlay() {
    fullPlay.textContent = playing ? 'Ⅱ' : '▶';
    fullPlay.setAttribute('aria-label', playing ? 'Pause' : 'Play');
    topPlay.textContent = playing ? 'Ⅱ' : '▶';
    topPlay.setAttribute('aria-label', playing ? 'Pause' : 'Play');
  }
  function startTimer() {
    clearInterval(timer);
    if (playing) timer = setInterval(() => {
      seconds = seconds >= 89 ? 0 : seconds + 1;
      const mins = Math.floor(seconds / 60);
      const secs = String(seconds % 60).padStart(2, '0');
      document.getElementById('elapsed').textContent = mins + ':' + secs;
      const pct = Math.min(88, 13 + (seconds - 11) * .9);
      document.getElementById('progressFill').style.width = pct + '%';
      document.getElementById('progressKnob').style.left = pct + '%';
    }, 1000);
  }
  openPlayer.addEventListener('click', () => {
    player.classList.add('open');
    playing = true;
    updatePlay();
    startTimer();
  });
  closePlayer.addEventListener('click', () => {
    player.classList.remove('open');
    clearInterval(timer);
  });
  fullPlay.addEventListener('click', () => { playing = !playing; updatePlay(); startTimer(); });
  topPlay.addEventListener('click', () => { playing = !playing; updatePlay(); startTimer(); });
